/*
 * WHAT THEY MUST PRODUCE, AND WHAT EACH OBJECTIVE HOLDS (TASK-L166 §2).
 *
 * PORTED, NEVER RE-DERIVED. Sources, in the product's repo:
 *   dossierProgress                  -> src/lib/server/delivery/dossier-map.ts
 *   humaniseFactName, toMarkdown     -> src/lib/components/course/dossier-format.ts
 *   archived off the learner's meter -> src/lib/server/deliverables/resolve.ts
 *                                       (getEffectiveDeliverables)
 *   label, fillPct, the aria + caption,
 *     submissions under an objective -> src/lib/components/course/DossierMeter.tsx
 *   "What they have told us"         -> src/lib/components/staff/ObjectivesPanel.tsx
 *                                       + server/coach/dossier-service.ts (the split)
 * `tools/check-dossier.mjs` runs THIS script and the product's own
 * `dossierProgress` over the same inputs and compares every field.
 *
 * ONE OWNER FOR BOTH SURFACES. The learner's meter (L167) and the coach's
 * "What they must produce" (L168) both read these segments. If each derived
 * them, a learner and their coach could disagree about what was captured under
 * which objective — L86, one layer up.
 *
 * THE ONE ASYMMETRY IS DECIDED HERE AND NOWHERE ELSE. An ARCHIVED objective is
 * off the learner's meter and still on the coach's list; its facts stay for
 * both. The product decides it in a query; the template has no query, so the
 * fixture carries every row and this filter is the rule.
 *
 * NOTHING HERE SAYS WHETHER AN OBJECTIVE IS COMPLETE. No `done`, no
 * `complete`, no `remaining`, no `missing` — L114's guard ("nothing anywhere
 * computes whether a deliverable is complete"), upstream of gating, counting and
 * ranking all three. `fillPct` is a bar WIDTH and is never rendered as a number.
 */
function plain(x) {
  if (x === null || x === undefined) return x;
  if (Array.isArray(x)) return x.map(plain);
  if (typeof x === 'object') {
    if (typeof x.get === 'function' && x.data && typeof x.data === 'object') return plain(x.data);
    if (Array.isArray(x.items)) return plain(x.items);
    const out = {};
    for (const k of Object.keys(x)) out[k] = plain(x[k]);
    return out;
  }
  return x;
}

/* NOT ARRIVED YET IS NOT THE SAME AS WIRED WRONG (L164). An absent copy waits —
   this node runs again the moment it lands — and a copy that ARRIVES without a
   `dossier` namespace is a named failure. No fallback words here: this
   component only ever sits beside Data/Strings, and a second copy of the words
   is the drift the string table exists to stop. */
if (Inputs.copy === undefined || Inputs.copy === null) return;
const COPY = (plain(Inputs.copy) || {}).dossier;
if (!COPY || !COPY.asksFor || !COPY.factsCaptured_other) {
  throw new Error('Logic/Dossier: no `dossier` copy. Wire Data/Strings.copy into Copy (TASK-L166).');
}

/* WHO IS READING, from Data/Strings' validated output. No default (L163 §3). */
const audience = String(Inputs.audience || '').trim();
if (audience !== 'learner' && audience !== 'coach') {
  throw new Error('Logic/Dossier: Audience must be "learner" or "coach", not "' + audience + '" (TASK-L166).');
}

function fill(template, values) {
  return String(template).replace(/\{(\w+)\}/g, (m, k) => (values[k] === undefined ? m : String(values[k])));
}
function plural(one, other, n) {
  return fill(n === 1 ? one : other, { n: n });
}

/* ── dossier-map.ts: dossierProgress, VERBATIM ─────────────────────────────
   A fact under a deliverable's prefix but not in its expectedCoreFields still
   counts toward `totalCaptured`: the learner is never penalised for this map
   being incomplete. A key with no dot, or whose prefix is not a slug in the set
   it was GIVEN, is ignored — which is exactly how an archived objective stops
   being counted while its facts stay where they are. */
function dossierProgress(facts, deliverables) {
  const bySlug = new Map(deliverables.map((d) => [d.slug, d]));
  const buckets = new Map();
  for (const deliverable of deliverables) {
    buckets.set(deliverable.slug, []);
  }

  for (const [field, value] of Object.entries(facts)) {
    const dotIndex = field.indexOf('.');
    if (dotIndex === -1) continue;

    const prefix = field.slice(0, dotIndex);
    const factName = field.slice(dotIndex + 1);
    if (!bySlug.has(prefix)) continue;

    buckets.get(prefix).push({ field, factName, value });
  }

  return deliverables.map((deliverable) => {
    const expectedCoreFields = deliverable.expectedCoreFields;
    const captured = buckets.get(deliverable.slug);
    // Expected core fields lead (in deliverable order), extras keep encounter
    // order — a stable sort by expected-rank does both.
    const rank = (factName) => {
      const i = expectedCoreFields.indexOf(factName);
      return i === -1 ? expectedCoreFields.length : i;
    };
    const ordered = captured
      .map((fact, i) => ({ fact, i }))
      .sort((a, b) => rank(a.fact.factName) - rank(b.fact.factName) || a.i - b.i)
      .map(({ fact }) => fact);

    return {
      slug: deliverable.slug,
      labelKey: deliverable.labelKey,
      ...(deliverable.title ? { title: deliverable.title } : {}),
      ...(deliverable.id ? { deliverableId: deliverable.id } : {}),
      expectedTotal: expectedCoreFields.length,
      expectedFields: [...expectedCoreFields],
      capturedExpected: captured.filter((f) => expectedCoreFields.includes(f.factName)).length,
      totalCaptured: captured.length,
      captured: ordered,
    };
  });
}

/* ── dossier-format.ts: humaniseFactName and toMarkdown, VERBATIM ──────────
   `humaniseFactName` does NOT split a namespace — "a.bC" becomes "A.b c". That
   is ported as it is; the coach's labels below route around it rather than
   carrying the product's defect (§3). */
function humaniseFactName(factName) {
  const spaced = factName
    .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
    .replace(/[_-]+/g, ' ')
    .trim()
    .toLowerCase();
  return spaced.charAt(0).toUpperCase() + spaced.slice(1);
}

function toMarkdown(label, captured) {
  const body = captured
    .map((f) => `**${humaniseFactName(f.factName)}**\n${f.value}`)
    .join('\n\n');
  return `## ${label}\n\n${body}\n`;
}

const all = plain(Inputs.deliverables) || [];
const facts = plain(Inputs.facts) || {};
const submissions = plain(Inputs.submissions) || [];
const onboardingFacts = plain(Inputs.onboardingFacts) || [];

/* Concept id -> the title on their path (DossierMeter's `stepTitleByConceptId`).
   A concept with no title renders its SLUG, as the product's `?? id` does,
   rather than vanishing from the list of what an objective needs. */
const titles = new Map((plain(Inputs.concepts) || []).map((c) => [c.id, c.title]));
const titleOf = (id) => (titles.has(id) ? titles.get(id) : id);

/* The trainer's own title wins; otherwise the pack's label by `labelKey`. An
   authored title is DATA and is never looked up in the table (L27/L112). A
   `labelKey` the table does not have renders the key rather than nothing — the
   product's i18next would show `dossier.deliverable.<key>`, which is the same
   failure dressed as a path. */
function labelOf(d) {
  if (d.title) return d.title;
  const pack = COPY.deliverable || {};
  return pack[d.labelKey] !== undefined ? pack[d.labelKey] : d.labelKey;
}

/* getEffectiveDeliverables excludes archived rows for the LEARNER. The coach's
   list (DeliverablesTab) shows every row, archived ones marked. */
const shown = audience === 'learner' ? all.filter((d) => !d.archivedAt) : all;
const bySlug = new Map(all.map((d) => [d.slug, d]));

const segments = dossierProgress(facts, shown).map((seg, i) => {
  const d = shown[i];
  const label = labelOf(d);
  const hasFacts = seg.totalCaptured > 0;
  const out = Object.assign({}, seg, {
    label: label,
    /* What it asks for, in the objective's own order — the NAMES, never a count
       of them (L144 §2: an empty objective opens to what it is for). */
    asksFor: seg.expectedFields.map(humaniseFactName),
    captured: seg.captured.map((f) => Object.assign({}, f, { name: humaniseFactName(f.factName) })),
    hasFacts: hasFacts,
    /* DossierMeter's own arithmetic. A bar width, never printed. */
    fillPct:
      seg.expectedTotal > 0
        ? Math.min(100, Math.round((seg.capturedExpected / seg.expectedTotal) * 100))
        : 0,
    /* "3 facts captured" is additive — what IS there, never what is not. An
       empty objective carries no caption at all, not "0 facts". */
    caption: hasFacts ? plural(COPY.factsCaptured_one, COPY.factsCaptured_other, seg.totalCaptured) : '',
    ariaLabel: fill(hasFacts ? COPY.openAria : COPY.openEmptyAria, { label: label }),
    /* Work filed against THIS objective (L114 §4). Compared as the product
       compares it, `deliverableId === deliverableId`: an unfiled submission
       (null) appears under no objective. */
    submissions: submissions
      .filter((sub) => sub.deliverableId === seg.deliverableId)
      .map((sub) => ({ conceptId: sub.conceptId, title: titleOf(sub.conceptId), submittedAt: sub.submittedAt })),
    markdown: toMarkdown(label, seg.captured)
  });
  if (audience === 'coach') {
    out.description = d.description || '';
    out.archived = !!d.archivedAt;
    out.position = d.position;
    out.requires = (d.conceptIds || []).map((id) => ({ id: id, title: titleOf(id) }));
  }
  return out;
});

/* ── WHAT THEY HAVE TOLD US (coach only), and the defect NOT carried (§3) ───
   The product splits the facts into the pack's onboarding facts (authored
   labels) and everything else, each in capture order, and labels the rest with
   `humaniseFactName(key)` on the WHOLE key — so a coach reads
   `Observation log.what you saw`. Recorded three times in the product's
   CLAUDE.md as inherited LX14-era state. The template does not port it (L163's
   precedent): a namespaced key reads `<objective> · <fact>`, from the coach's
   full list so an ARCHIVED objective's answers are still named. */
const onboardingLabel = new Map(onboardingFacts.map((f) => [f.key, f.label]));
function toldLabel(key) {
  if (onboardingLabel.has(key)) return onboardingLabel.get(key);
  const dot = key.indexOf('.');
  if (dot === -1) return humaniseFactName(key);
  const prefix = key.slice(0, dot);
  const owner = bySlug.get(prefix);
  const head = owner ? labelOf(owner) : humaniseFactName(prefix);
  return head + ' · ' + humaniseFactName(key.slice(dot + 1));
}
const keys = Object.keys(facts);
const ordered = keys.filter((k) => onboardingLabel.has(k)).concat(keys.filter((k) => !onboardingLabel.has(k)));
const toldUs = audience === 'coach' ? ordered.map((k) => ({ id: k, label: toldLabel(k), value: String(facts[k]) })) : [];

Outputs.segments = segments;
Outputs.hasSegments = segments.length > 0;
Outputs.toldUs = toldUs;
Outputs.hasToldUs = toldUs.length > 0;
Outputs.loaded();
